CREATE SCHEMA IF NOT EXISTS event;

CREATE TABLE IF NOT EXISTS event.mails (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    event_id UUID NOT NULL,
    interval_nbr INTEGER NOT NULL DEFAULT 1 CHECK (interval_nbr >= 0),
    interval_unit event_interval_unit NOT NULL DEFAULT 'now',
    interval_kind event_interval_kind NOT NULL DEFAULT 'after_sub',
    notification_channel event_notification_channel NOT NULL DEFAULT 'mail',
    scheduled_date TIMESTAMPTZ,
    mail_done BOOLEAN NOT NULL DEFAULT FALSE,
    last_registration_id UUID,
    template_ref UUID,
    template_kind TEXT,
    error_datetime TIMESTAMPTZ,
    error_kind event_mail_error_kind,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_mails_event_id_interval_kind ON event.mails (event_id, interval_kind);

CREATE INDEX IF NOT EXISTS idx_mails_scheduled_date_mail_done ON event.mails (scheduled_date, mail_done);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_mails_metadata_gin ON event.mails USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_mails_metadata_deleted_at ON event.mails ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_mails_metadata_created_at ON event.mails ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_mails_metadata_updated_at ON event.mails ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION event.mails_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS mails_insert_audit ON event.mails;
CREATE TRIGGER mails_insert_audit BEFORE INSERT ON event.mails
    FOR EACH ROW EXECUTE FUNCTION event.mails_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS mails_update_audit ON event.mails;
CREATE TRIGGER mails_update_audit BEFORE UPDATE ON event.mails
    FOR EACH ROW EXECUTE FUNCTION event.mails_audit_timestamp();

